use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " --- Edit Application Functions ---"] fn apply_add_use (ast : & mut syn :: File , details : & AddUseDetails) -> Result < () > { let new_use_item : ItemUse = syn :: parse_str (& details . path) . with_context (| | format ! ("Invalid use statement syntax: {}" , details . path)) ? ; let new_use_str = quote ! { # new_use_item } . to_string () ; for item in & ast . items { if let Item :: Use (existing_use) = item { if quote ! { # existing_use } . to_string () == new_use_str { eprintln ! ("  Skipping duplicate use statement: {}" , details . path) ; return Ok (()) } } } match & details . position { Some (AddUsePosition :: Start) => { eprintln ! ("  Inserting use statement at start.") ; ast . items . insert (0 , Item :: Use (new_use_item . clone ())) ; } Some (AddUsePosition :: End) | None => { eprintln ! ("  Inserting use statement at end.") ; let mut last_use_idx = 0 ; for (idx , item) in ast . items . iter () . enumerate () { if let Item :: Use (_) = item { last_use_idx = idx ; } } ast . items . insert (last_use_idx + 1 , Item :: Use (new_use_item . clone ())) ; } Some (AddUsePosition :: AfterUsePath (after_path)) => { eprintln ! ("  Inserting use statement after path: {}" , after_path) ; let after_use_item : ItemUse = syn :: parse_str (after_path) . with_context (| | format ! ("Invalid 'after_use_path' syntax: {}" , after_path)) ? ; let after_use_str = quote ! { # after_use_item } . to_string () ; let mut inserted = false ; for (idx , item) in ast . items . iter () . enumerate () { if let Item :: Use (existing_use) = item { if quote ! { # existing_use } . to_string () == after_use_str { ast . items . insert (idx + 1 , Item :: Use (new_use_item . clone ())) ; inserted = true ; break ; } } } if ! inserted { eprintln ! ("  Warning: 'after_use_path' not found. Inserting at end of uses.") ; ast . items . push (Item :: Use (new_use_item)) ; } } } eprintln ! ("  Added use statement: {}" , details . path) ; Ok (()) }